  function showHelp(){ $('#modalRoot').innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal"><div class="modal-head"><div><h2>Recomendaciones de seguridad</h2><p>Usa la plataforma con responsabilidad.</p></div><button class="icon-button" data-close-modal>✕</button></div><div class="modal-body"><div class="detail-item"><strong>1. Si existe peligro inmediato</strong><p class="form-help">Contacta a los servicios de emergencia locales. No esperes a que una alerta comunitaria sea atendida.</p></div><div class="detail-item"><strong>2. Describe hechos observables</strong><p class="form-help">Indica la ubicación y lo que viste. Evita acusaciones no verificadas o exponerte para conseguir evidencia.</p></div><div class="detail-item"><strong>3. Cuida la privacidad</strong><p class="form-help">No publiques datos personales innecesarios. La información de contacto del reportante se reserva para los roles autorizados.</p></div><div class="detail-item"><strong>4. Evita falsas alarmas</strong><p class="form-help">Si reportaste por error, marca el reporte como falsa alarma cuando la opción esté disponible.</p></div></div><div class="modal-foot"><button class="btn btn-primary" data-close-modal>Entendido</button></div></section></div>`; }
  function showPasswordReset(){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-head"><div><h2>Crear nueva contraseña</h2><p>Elige una contraseña segura de al menos 8 caracteres.</p></div></div><form id="resetPasswordForm"><div class="modal-body"><label class="field-label">Nueva contraseña<input class="field-control" id="newPassword" type="password" minlength="8" required></label></div><div class="modal-foot"><button class="btn btn-primary" type="submit">Guardar contraseña</button></div></form></section></div>`;}
  function syncPending(){if(!navigator.onLine||!supabase||!state.user)return;const pending=JSON.parse(localStorage.getItem('av_pending')||'[]');if(!pending.length)return;(async()=>{const left=[];for(const p of pending){try{await createIncident(p);}catch(e){left.push(p);}}localStorage.setItem('av_pending',JSON.stringify(left));if(pending.length>left.length){toast('Alertas sincronizadas',`${pending.length-left.length} alerta(s) pendiente(s) enviada(s).`);await loadRemote();renderPage();}})();}
  async function boot(){loadDemo();bindGlobal();$('#demoNote').classList.toggle('hidden',!!supabase);if(supabase){$('#demoNote').classList.add('hidden');$('#connectionStatus span').textContent='Conectado a Supabase';$('#connectionStatus').classList.add('online');try{const {data:{session}}=await supabase.auth.getSession();if(session){const {data:profile}=await supabase.from('profiles').select('*').eq('id',session.user.id).single();if(profile&&profile.active!==false)enterApp({...profile,email:session.user.email},false);}}catch(e){console.warn('Sesión no recuperada',e);}supabase.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'&&!$('#appView').classList.contains('hidden')){state.user=null;$('#appView').classList.add('hidden');$('#authView').classList.remove('hidden');}if(event==='PASSWORD_RECOVERY')showPasswordReset();});}else{$('#connectionStatus span').textContent='Modo demostración';}window.addEventListener('online',syncPending);window.addEventListener('offline',()=>toast('Sin conexión','Los reportes nuevos se guardarán temporalmente en este dispositivo.','error'));}
  window.AV={state,toast,pushNotification,renderPage,loadDemo,loadResponses,loadRemote,category,hasCoords,isActive,esc,supabase,cfg,mapConfigured,getPosition,ipPosition,updatePosition,fmtDate,ago,saveDemo};
  boot();
